// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Map;

import org.junit.jupiter.api.Test;

class BagEstimateEvidenceStateTest {

	private static final String PACKAGE = "org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.";

	@Test
	void bagEstimateExposesOptionalQueryLocalEvidenceStateSidecar() {
		assertDoesNotThrow(() -> {
			Class<?> reference = Class.forName(PACKAGE + "EvidenceStateRef");
			Class.forName(PACKAGE + "EvidenceStateSummary");
			Class.forName(PACKAGE + "FrontierLayout");
			Class.forName(PACKAGE + "FrontierStateArena");
			BagEstimate.class.getMethod("evidenceState");
			BagEstimate.class.getMethod("withEvidenceState", reference);
			BagEstimate.class.getMethod("withoutEvidenceState");
		});
	}

	@Test
	void scalarConstructorsRemainStateFreeAndScalarIdentityIgnoresSidecar() {
		BagEstimate scalar = BagEstimate.exact(7.0d, "exact");
		try (FrontierStateArena arena = new FrontierStateArena(64 * 1024L)) {
			EvidenceStateRef state = arena.append(FrontierLayout.of("x"), EvidenceStateSummary.exact(7.0d));
			BagEstimate stateful = scalar.withEvidenceState(state);

			assertTrue(scalar.evidenceState().isEmpty());
			assertEquals(state, stateful.evidenceState().orElseThrow());
			assertEquals(scalar, stateful);
			assertEquals(scalar.hashCode(), stateful.hashCode());
			assertFalse(stateful.toString().contains("EvidenceStateRef"));
			assertNotSame(scalar, stateful);
			assertSame(scalar, scalar.withoutEvidenceState());
			assertEquals(scalar, stateful.withoutEvidenceState());
		}
	}

	@Test
	void everyEstimateTransformRetainsFrontierStateUntilExplicitDetachment() {
		try (FrontierStateArena arena = new FrontierStateArena(64 * 1024L)) {
			EvidenceStateRef state = arena.append(FrontierLayout.of("x"), EvidenceStateSummary.exact(7.0d));
			BagEstimate estimate = BagEstimate.exact(7.0d, "exact").withEvidenceState(state);

			assertEquals(state, estimate.withWorkRows(9.0d, "work").evidenceState().orElseThrow());
			assertEquals(state, estimate.withMemoryRows(2.0d, "memory").evidenceState().orElseThrow());
			assertEquals(state, estimate.withMetrics(Map.of("metric", 1.0d)).evidenceState().orElseThrow());
			assertEquals(state, estimate.withRows(8.0d, "changed-rows").evidenceState().orElseThrow());
			assertEquals(state,
					estimate.withVariable("x", VariableEstimate.bound(7.0d, 1.0d)).evidenceState().orElseThrow());
			assertEquals(state, estimate.withRowsPreservingEvidence(8.0d, 9.0d, 0.8d, "rebased",
					Map.of("metric", 2.0d), false).evidenceState().orElseThrow());
			assertTrue(estimate.withoutEvidenceState().evidenceState().isEmpty());
		}
	}
}
